// Index pour recherche rapide par code postal
export const postalCodesByCode = postalCodes.reduce((acc, item) => {
  if (item.Codepos !== null && item.Codepos !== undefined) {
    const code = item.Codepos.toString();
    if (!acc[code]) acc[code] = [];
    acc[code].push(item);
  }
  return acc;
}, {});

// Index par département
export const postalCodesByDepartement = postalCodes.reduce((acc, item) => {
  if (item.Departement) {
    if (!acc[item.Departement]) acc[item.Departement] = [];
    acc[item.Departement].push(item);
  }
  return acc;
}, {});

// Index par code INSEE
export const postalCodesByINSEE = postalCodes.reduce((acc, item) => {
  if (item.INSEE) {
    acc[item.INSEE] = item;
  }
  return acc;
}, {});

/**
 * Récupère les communes correspondant à un code postal
 * @param {string} postalCode - Le code postal à rechercher (5 chiffres)
 * @returns {Array} - Liste des communes correspondantes
 */
export function getCommunesByPostalCode(postalCode) {
  return postalCodesByCode[postalCode] || [];
}

/**
 * Récupère toutes les communes d'un département
 * @param {string} departement - Le nom du département
 * @returns {Array} - Liste des communes du département
 */
export function getCommunesByDepartement(departement) {
  return postalCodesByDepartement[departement] || [];
}

/**
 * Récupère une commune par son code INSEE
 * @param {string} insee - Le code INSEE de la commune
 * @returns {Object|undefined} - La commune correspondante
 */
export function getCommuneByINSEE(insee) {
  return postalCodesByINSEE[insee];
}

/**
 * Recherche des communes par nom (partiel)
 * @param {string} query - Le texte à rechercher
 * @param {number} limit - Nombre maximum de résultats (défaut: 10)
 * @returns {Array} - Liste des communes correspondantes
 */
export function searchCommunesByName(query, limit = 10) {
  const normalized = query.toUpperCase().trim();
  return postalCodes
    .filter(c => c.Commune.includes(normalized))
    .slice(0, limit);
}

/**
 * Autocomplétion de communes
 * @param {string} query - Le début du nom de commune
 * @param {number} limit - Nombre maximum de résultats (défaut: 10)
 * @returns {Array} - Liste des communes commençant par la requête
 */
export function autocompleteCommuneName(query, limit = 10) {
  const normalized = query.toUpperCase().trim();
  return postalCodes
    .filter(c => c.Commune.startsWith(normalized))
    .slice(0, limit);
}

/**
 * Recherche par code postal (supporte les codes incomplets)
 * @param {string} query - Le début du code postal
 * @param {number} limit - Nombre maximum de résultats (défaut: 10)
 * @returns {Array} - Liste des communes correspondantes
 */
export function searchByPostalCode(query, limit = 10) {
  if (!query) return [];
  const normalized = query.toString().trim();
  return postalCodes
    .filter(
      c =>
        c.Codepos !== null &&
        c.Codepos !== undefined &&
        c.Codepos.toString().startsWith(normalized)
    )
    .slice(0, limit);
}

/**
 * Valide un code postal français
 * @param {string} code - Le code postal à valider
 * @returns {boolean} - true si le code postal existe
 */
export function validateFrenchPostalCode(code) {
  if (!code || code.length !== 5) return false;
  const communes = getCommunesByPostalCode(code);
  return communes.length > 0;
}

/**
 * Obtient le département à partir d'un code postal
 * @param {string} postalCode - Le code postal
 * @returns {string|null} - Le nom du département ou null
 */
export function getDepartementFromPostalCode(postalCode) {
  const communes = getCommunesByPostalCode(postalCode);
  return communes.length > 0 ? communes[0].Departement : null;
}

/**
 * Formate un code postal (ajoute les zéros initiaux si nécessaire)
 * @param {string|number} code - Le code postal à formater
 * @returns {string} - Le code postal formaté sur 5 chiffres
 */
export function formatPostalCode(code) {
  if (!code && code !== 0) return "";
  return code.toString().padStart(5, "0");
}

// Export default pour import simplifié
export default {
  postalCodes,
  postalCodesByCode,
  postalCodesByDepartement,
  postalCodesByINSEE,
  getCommunesByPostalCode,
  getCommunesByDepartement,
  getCommuneByINSEE,
  searchCommunesByName,
  autocompleteCommuneName,
  searchByPostalCode,
  validateFrenchPostalCode,
  getDepartementFromPostalCode,
  formatPostalCode
};
